INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q1 Item 1 (TPS 2016): Com relação às ideias desenvolvidas no texto I, julgue (C ou E) os itens subsequentes. | O trecho “paisagem deveras anônima” (R. 64 e 65), que apresenta expressão atribuída a Gobineau, faz referência a um lugar novo e ainda desconhecido, tendo sentido similar ao do trecho “um mundo inteiramente inédito” (R. 63 e 64).', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q1 Item 2 (TPS 2016): Com relação às ideias desenvolvidas no texto I, julgue (C ou E) os itens subsequentes. | Segundo o autor do texto, Blaise Cendrars foi instigado a viajar ao Brasil devido à existência, no país, de ritmos musicais exóticos, entre os quais o maxixe.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q1 Item 3 (TPS 2016): Com relação às ideias desenvolvidas no texto I, julgue (C ou E) os itens subsequentes. | Darius Milhaud, compositor que exerceu funções diplomáticas no Rio de Janeiro, inspirou-se na música popular carioca para compor o Boeuf sur le Toît.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q1 Item 4 (TPS 2016): Com relação às ideias desenvolvidas no texto I, julgue (C ou E) os itens subsequentes. | Porquanto, conforme o texto, Blaise Cendrars era “Viajante sem bagagem e sem descanso” (R.8) e exibia “o irônico desprendimento do turista ocasional” (R.73), é correto concluir que o “poeta do Transiberiano” (R. 8 e 9) viajava ao acaso, sem que o motivasse maior curiosidade pelos lugares a que se dirigia.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q2 Item 1 (TPS 2016): Julgue (C ou E) os itens a seguir, relativos às ideias desenvolvidas no texto I. | O autor do texto informa sobre a criativa parceria de Darius Milhaud, Paul Claudel e Blaise Cendrars, determinante para a composição de obras coletivas dos três artistas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q2 Item 2 (TPS 2016): Julgue (C ou E) os itens a seguir, relativos às ideias desenvolvidas no texto I. | Ao fazer referência à “moda primitivista” (R.34), Alexandre Eulálio trata do Brasil, “país novo, quase um desconhecido de si mesmo” (R. 14 e 15), que fascinava a imaginação de Blaise Cendrars.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q2 Item 3 (TPS 2016): Julgue (C ou E) os itens a seguir, relativos às ideias desenvolvidas no texto I. | Conforme o texto, Blaise Cendrars deixou-se influenciar pelos temas nativistas e pelo “vasto folclore nacional” (R.53) que encontrou ao chegar ao Brasil e manter contato com os compositores do país.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q2 Item 4 (TPS 2016): Julgue (C ou E) os itens a seguir, relativos às ideias desenvolvidas no texto I. | Os títulos de Blaise Cendrars citados no texto, tais como Les Pâques à New York, Prose du Transsibérien e Panama, salientam a tendência do poeta suíço para os comentários sobre viagens, em sua obra, e seu interesse em conhecer lugares. ||263_IRBR_DIPL_1F_001_01N569592|| CESPE | CEBRASPE – IRBr Diplomata – Aplicação: 2016', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q3 Item 1 (TPS 2016): Cada um dos itens subsequentes apresenta um trecho do texto I, seguido de uma proposta de reescrita desse trecho. Julgue cada item como certo (C), se sua reescrita mantiver as informações originais do trecho, ou como errado (E), se essa reescrita acarretar prejuízo às informações originais. 1 “É depois da publicação da Anthologie que o compositor Darius Milhaud, interessado pelo jazz desde o final da guerra, procura a colaboração do poeta para um balé de tema negro que deseja compor.” (R. 35 a 3 | O índio não teve muita sorte na literatura brasileira, depois do Romantismo. Enquanto nas letras hispano-americanas viceja um esplêndido indigenismo pelo', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q3 Item 2 (TPS 2016): Cada um dos itens subsequentes apresenta um trecho do texto I, seguido de uma proposta de reescrita desse trecho. Julgue cada item como certo (C), se sua reescrita mantiver as informações originais do trecho, ou como errado (E), se essa reescrita acarretar prejuízo às informações originais. 1 “É depois da publicação da Anthologie que o compositor Darius Milhaud, interessado pelo jazz desde o final da guerra, procura a colaboração do poeta para um balé de tema negro que deseja compor.” (R. 35 a 3 | século XX adentro, com tantos e tão importantes criadores dedicando-se a transpor o índio para a ficção, no Brasil se podem contar nos dedos das mãos os casos. 7 Torna a trazer o assunto à baila o aparecimento e grande vendagem de Maíra, romance de Darcy Ribeiro. O renomado antropólogo já tinha em seu acervo de realizações 10 uma respeitável brasiliana, incluindo vários trabalhos sobre os índios, um dos quais, a história de Uirá, fora transformado em filme no início da d', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q4 Item 1 (TPS 2016): Com relação às ideias desenvolvidas no texto II, julgue (C ou E) os itens subsecutivos. | Ao afirmar que o “índio não teve muita sorte na literatura brasileira” (R.1), a autora indica que a representação literária dos personagens indígenas em romances brasileiros foi marcada pela presença do iñaron, “estado de fúria sagrada, associado ao sofrimento excessivo” (R. 20 e 21).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q4 Item 2 (TPS 2016): Com relação às ideias desenvolvidas no texto II, julgue (C ou E) os itens subsecutivos. | A autora considera que o romance Maíra é uma incursão do romancista e antropólogo Darcy Ribeiro pelo épico e opina que um “narrador coletivo índio” (R.44) é responsável pelos melhores trechos da mencionada obra literária.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q4 Item 3 (TPS 2016): Com relação às ideias desenvolvidas no texto II, julgue (C ou E) os itens subsecutivos. | Conforme o texto, iñaron é palavra tupi que não é apropriada para denotar o sofrimento de todas as tribos indígenas, mas poderia denotar os sentimentos de fúria de heróis gregos como Agave e Aquiles.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q4 Item 4 (TPS 2016): Com relação às ideias desenvolvidas no texto II, julgue (C ou E) os itens subsecutivos. | Ao comparar a representação do índio na literatura brasileira com a do índio na literatura hispano-americana, a autora conclui que romances com percepção antropológica costumam ser mais raros e tendem a incursionar pelo épico.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q5 Item 1 (TPS 2016): Julgue (C ou E) os itens seguintes, relacionados às ideias desenvolvidas no texto II. | Ao citar exemplos da literatura grega antiga, Walnice Nogueira Galvão indica que a organização tribal é capaz de gerar conflitos e tensões que transcendem o Brasil ou o espaço hispano-americano.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q5 Item 2 (TPS 2016): Julgue (C ou E) os itens seguintes, relacionados às ideias desenvolvidas no texto II. | Com o trecho “encontram-se, estonteados, os índios” (R.37), a autora do texto evidencia o confronto entre o “capitalismo selvagem no país” (R. 33 e 34) e a cultura indígena.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q5 Item 3 (TPS 2016): Julgue (C ou E) os itens seguintes, relacionados às ideias desenvolvidas no texto II. | Tanto o romance Maíra quanto o relato de Uirá exibem enredos marcados pelas dificuldades enfrentadas por tribos indígenas, atingidas por flagelos trazidos pela civilização não indígena.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q5 Item 4 (TPS 2016): Julgue (C ou E) os itens seguintes, relacionados às ideias desenvolvidas no texto II. | Ao afirmar que “o índio está mais vivo do que nunca em sua conexão com a literatura” (R. 49 e 50), a autora defende que romances como Maíra têm o mérito de salvar tribos e civilizações indígenas das forças destrutivas que predominam nas sociedades.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q6 Item 1 (TPS 2016): Acerca das relações semântico-sintáticas e do vocabulário do texto II, julgue (C ou E) os itens seguintes. | Na oração que inicia o segundo parágrafo, o verbo concorda com o primeiro núcleo do sujeito posposto, concordância verbal abonada pela gramática normativa.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q6 Item 2 (TPS 2016): Acerca das relações semântico-sintáticas e do vocabulário do texto II, julgue (C ou E) os itens seguintes. | Mantendo-se a correção gramatical do texto, o segmento “fora transformado em filme” (R. 11 e 12) poderia ser reescrito da seguinte forma: foi transposto para o cinema.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q6 Item 3 (TPS 2016): Acerca das relações semântico-sintáticas e do vocabulário do texto II, julgue (C ou E) os itens seguintes. | Os termos “trágico” (R.15), “de Uirá” (R.16) e “deste século” (R.16) exercem a mesma função sintática, na oração em que ocorrem.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q6 Item 4 (TPS 2016): Acerca das relações semântico-sintáticas e do vocabulário do texto II, julgue (C ou E) os itens seguintes. | Sem prejuízo da correção gramatical e do sentido do texto, a expressão “contar nos dedos das mãos” (R.6) poderia ser substituída por contar pelos dedos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q7 Item 1 (TPS 2016): Considerando as relações semântico-sintáticas estabelecidas no texto II, julgue (C ou E) os itens a seguir. 1 As relações semântico-sintáticas no período “Nas Bacantes, do mesmo autor, Agave, fora de si, participa do desmembramento de seu filho adulto, Penteu, rei de Tebas” (R. 26 e 27) sustentam a inferência de que Agave tinha mais de um filho e apenas um deles era adulto. 2 O trecho “viceja um esplêndido indigenismo” (R.3) indica que, para a autora, prosperou na literatura hispano-americana, d | Pergunto: e agora? Como é que meu Padrinho foi degolado num quarto de pesadas paredes sem janelas, cuja porta fora trancada, por dentro, por ele mesmo? Como foi que', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q7 Item 2 (TPS 2016): Considerando as relações semântico-sintáticas estabelecidas no texto II, julgue (C ou E) os itens a seguir. 1 As relações semântico-sintáticas no período “Nas Bacantes, do mesmo autor, Agave, fora de si, participa do desmembramento de seu filho adulto, Penteu, rei de Tebas” (R. 26 e 27) sustentam a inferência de que Agave tinha mais de um filho e apenas um deles era adulto. 2 O trecho “viceja um esplêndido indigenismo” (R.3) indica que, para a autora, prosperou na literatura hispano-americana, d | os assassinos ali penetraram, sem ter por onde? Como foi que saíram, deixando o quarto trancado por dentro? Quem foram esses assassinos? Como foi que raptaram Sinésio, aquele rapaz 7 alumioso, que concentrava em si as esperanças dos Sertanejos por um Reino de glória, de justiça, de beleza e de grandeza para todos? Bem, não posso avançar nada, porque aí é que está 10 o nó! Este é o “centro de enigma e sangue” da minha história. Lembro que o genial poeta Nicolau Fagundes V', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q8 Item 1 (TPS 2016): Com relação às ideias desenvolvidas no texto III, julgue (C ou E) os próximos itens. | O narrador do texto apresenta um “insolúvel enredo de ‘romance de crime e sangue’” (R. 24 e 25), a partir de um episódio familiar, constituído pela degola do seu padrinho e pelo rapto de Sinésio.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q8 Item 2 (TPS 2016): Com relação às ideias desenvolvidas no texto III, julgue (C ou E) os próximos itens. | O narrador classifica Tobias Barreto de “excelso Gênio brasileiro” (R.32) por este haver escrito um romance que não expressou a índole de um povo superficial, uma vez que a narrativa se revelou enigmática e sangrenta.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q8 Item 3 (TPS 2016): Com relação às ideias desenvolvidas no texto III, julgue (C ou E) os próximos itens. | Para o narrador, a formação territorial do Brasil foi um ato de bravura que poderia fazer os brasileiros ultrapassarem os feitos narrados por Homero.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q8 Item 4 (TPS 2016): Com relação às ideias desenvolvidas no texto III, julgue (C ou E) os próximos itens. | Conforme o narrador, brasileiros como Nicolau Fagundes Varela e Tobias Barreto escreveram contra os brasileiros, incapazes, para ambos, de decifrar os enigmas do país e de fazer aparecer um romance de gênio.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q9 Item 1 (TPS 2016): Julgue (C ou E) os itens subsequentes, relativos às ideias desenvolvidas no texto III. | Em “E comenta, ácido” (R.39), a palavra “ácido” foi empregada, com ironia, para ridicularizar o Desembargador Pontes Visgueiro, criminoso de Alagoas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q9 Item 2 (TPS 2016): Julgue (C ou E) os itens subsequentes, relativos às ideias desenvolvidas no texto III. | Além de revelar sua identidade e algumas de suas alcunhas, o narrador do texto declara-se apto a, com sua história, superar os irônicos, sejam eles estrangeiros ou não.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q9 Item 3 (TPS 2016): Julgue (C ou E) os itens subsequentes, relativos às ideias desenvolvidas no texto III. | O trecho “Até na estatística criminal o nosso país revela-se mesquinho” (R. 42 e 43), atribuído pelo narrador a Tobias Barreto, indica que os ‘irônicos estrangeiros’ ridicularizam a pouca capacidade dos brasileiros de conhecerem a realidade em que vivem.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q9 Item 4 (TPS 2016): Julgue (C ou E) os itens subsequentes, relativos às ideias desenvolvidas no texto III. | Em “somos incapazes de forjar uma verdadeira trança, uma intrincada teia” (R. 23 e 24), a palavra “trança” foi empregada no sentido de trama. ||263_IRBR_DIPL_1F_001_01N569592|| CESPE | CEBRASPE – IRBr Diplomata – Aplicação: 2016', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q10 Item 1 (TPS 2016): Com referência ao texto III, julgue (C ou E) os itens que se seguem. 1 Sem prejuízo da informação veiculada no relato e da correção gramatical do texto, a vírgula empregada logo após “janelas” (R.2) poderia ser substituída pelo conector e. 2 No sintagma “os ‘irônicos estrangeiros’” (R. 21 e 22), o vocábulo ‘irônicos’ é o núcleo do sujeito, o que é confirmado pelo emprego de “irônico” em “desafio qualquer irônico” (R.58). 3 No trecho “porque eu, Dom Pedro Quaderna” (R.54), a conjunção “porque” é  | Em suas remotas origens helênicas, o termo “caráter” significou gravar. Empregavam-no, então, tanto para exprimir o sinete como a marca deixada na cera dócil. Essa dupla', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q10 Item 2 (TPS 2016): Com referência ao texto III, julgue (C ou E) os itens que se seguem. 1 Sem prejuízo da informação veiculada no relato e da correção gramatical do texto, a vírgula empregada logo após “janelas” (R.2) poderia ser substituída pelo conector e. 2 No sintagma “os ‘irônicos estrangeiros’” (R. 21 e 22), o vocábulo ‘irônicos’ é o núcleo do sujeito, o que é confirmado pelo emprego de “irônico” em “desafio qualquer irônico” (R.58). 3 No trecho “porque eu, Dom Pedro Quaderna” (R.54), a conjunção “porque” é  | significação ainda hoje é vernácula — se não corrente — em certas acepções. Na linguagem tipográfica, por exemplo, “caráter” tanto é o tipo da imprensa como o sinal ou a letra 7 gravada. Assim sendo, podemos dizer que o caráter de um homem não é somente o seu feitio moral, senão também a expressão e a impressão do indivíduo. Em arte, caráter será a 10 personalidade do autor, o aspecto aparente e profundo da obra e o efeito dela. Fixada assim a verdadeira acepção do term', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q11 Item 1 (TPS 2016): Com relação às ideias desenvolvidas no texto IV, julgue (C ou E) os itens a seguir. | O autor do excerto afirma que a crítica precisa levar em conta a intuição no julgamento e na análise da obra de arte.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q11 Item 2 (TPS 2016): Com relação às ideias desenvolvidas no texto IV, julgue (C ou E) os itens a seguir. | Na percepção do autor do texto, a simplicidade do poema Juca Mulato resulta da combinação entre a “obsessão do isolamento” (R.31) e os “modelos estranhos” (R.32) à criação literária.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q11 Item 3 (TPS 2016): Com relação às ideias desenvolvidas no texto IV, julgue (C ou E) os itens a seguir. | Alceu Amoroso Lima salienta a presença da tradição helênica no poema Juca Mulato, de Menotti del Picchia, marcante pela simplicidade, pela sobriedade e pelo caráter.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q11 Item 4 (TPS 2016): Com relação às ideias desenvolvidas no texto IV, julgue (C ou E) os itens a seguir. | Ao afirmar que Menotti del Picchia “procurou a naturalidade e não a arte” (R.18), o autor do texto indica que Juca Mulato é um “poema simples” (R.56), destituído de qualquer valor artístico. ||263_IRBR_DIPL_1F_001_01N569592|| CESPE | CEBRASPE – IRBr Diplomata – Aplicação: 2016', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q12 Item 1 (TPS 2016): Com relação às ideias desenvolvidas no texto IV, julgue (C ou E) os seguintes itens. | O autor do excerto valoriza a simplicidade do poema Juca Mulato, comparando-a à das sinfonias de Beethoven e à dos dramas musicais de Wagner, o que faria aumentar a receptividade dessas obras.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q12 Item 2 (TPS 2016): Com relação às ideias desenvolvidas no texto IV, julgue (C ou E) os seguintes itens. | Segundo Alceu Amoroso Lima, a “simplicidade radical” (R.76) de Juca Mulato, julgado comovente, não estimula a crítica a buscar nem “símbolos problemáticos” (R.69) nem “filosofias arbitrárias” (R. 69 e 70) na análise do poema.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q12 Item 3 (TPS 2016): Com relação às ideias desenvolvidas no texto IV, julgue (C ou E) os seguintes itens. | Embora afirme que os versos de Juca Mulato “Não são versos agradáveis, suaves ou elegantes” (R.42), o autor do texto os considera marcantes.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q12 Item 4 (TPS 2016): Com relação às ideias desenvolvidas no texto IV, julgue (C ou E) os seguintes itens. | A afirmação de que “O caráter desse livro se conserva pela ressonância que tem” (R. 41 e 42) indica que, para o crítico, os versos de Juca Mulato se perpetuam caso sejam lidos em voz alta ou declamados.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q13 Item 1 (TPS 2016): Com relação às ideias e às estruturas linguísticas do texto IV, julgue (C ou E) os itens a seguir. | Seriam mantidos o sentido original e a correção gramatical do trecho “se bem que a intuição íntima e a explicação individual sejam imprescindíveis” (R. 62 e 63), caso a expressão “se bem que” e a forma verbal “sejam” fossem substituídas, respectivamente, pelo termo porquanto e pela forma verbal são.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q13 Item 2 (TPS 2016): Com relação às ideias e às estruturas linguísticas do texto IV, julgue (C ou E) os itens a seguir. | A inserção de uma vírgula logo após “impossível”, em “um mal de amor impossível que leva a alma à desesperança” (R. 70 e 71), obrigaria à interpretação de que todo mal de amor impossível leva a alma a tal consequência.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q13 Item 3 (TPS 2016): Com relação às ideias e às estruturas linguísticas do texto IV, julgue (C ou E) os itens a seguir. | No período “Ganhou com isso (...) um eco natural” (R. 78 a 81), o sinal de dois-pontos poderia ser substituído por um travessão, sem que o sentido do texto e sua correção gramatical fossem prejudicados.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q13 Item 4 (TPS 2016): Com relação às ideias e às estruturas linguísticas do texto IV, julgue (C ou E) os itens a seguir. | O trecho “se não corrente” (R.4) poderia ser corretamente substituído por se não for corrente, preservando-se o sentido original do texto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q14 Item 1 (TPS 2016): Julgue (C ou E) os itens seguintes, relativos a acentuação de palavras e a aspectos gramaticais do texto IV. | No trecho “É certo que a evidência da beleza não pode ser em arte um critério axiomático” (R. 57 a 59), tanto o termo “certo” quanto o termo “axiomático” caracterizam, respectivamente, referentes que constituem sujeitos oracionais.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q14 Item 2 (TPS 2016): Julgue (C ou E) os itens seguintes, relativos a acentuação de palavras e a aspectos gramaticais do texto IV. | No texto, com a expressão “essa arte de titãs” (R.62), o autor faz referência à arte da música.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q14 Item 3 (TPS 2016): Julgue (C ou E) os itens seguintes, relativos a acentuação de palavras e a aspectos gramaticais do texto IV. | A forma “pôde” (R.22) poderia ser corretamente substituída por pode, visto que o seu tempo verbal é depreendido pelo contexto do parágrafo e que o acento nela empregado é opcional.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Portuguesa', NULL, 'Q14 Item 4 (TPS 2016): Julgue (C ou E) os itens seguintes, relativos a acentuação de palavras e a aspectos gramaticais do texto IV. | Os pronomes demonstrativos “isso” (R.47) e “esse” (R.48) retomam, respectivamente, o sentido de julgar e decompor as obras e o de processo. POLÍTICA INTERNACIONAL', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Política Internacional', NULL, 'Q15 Item 1 (TPS 2016): As implicações da globalização para o Estado-nação incluem o impacto sobre sua capacidade de formular autonomamente políticas econômicas no âmbito doméstico, uma vez que ele está muito mais sujeito a pressões e a constrangimentos estruturais do sistema internacional que em outras épocas. A esse respeito, julgue (C ou E) os itens a seguir. | Diferentes economias têm investido em fórmulas regionais de integração produtiva, optando por acordos preferenciais de alcance regional, a partir de maior demanda de países vizinhos para a importação de manufaturas procedentes das respectivas regiões, como é o caso da Ásia-Pacífico e da América do Sul. Nesse modelo, economias menores exportam bens de produção para as maiores (como Brasil e China), as quais, por sua vez, exportam bens finais para as menores.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Política Internacional', NULL, 'Q15 Item 2 (TPS 2016): As implicações da globalização para o Estado-nação incluem o impacto sobre sua capacidade de formular autonomamente políticas econômicas no âmbito doméstico, uma vez que ele está muito mais sujeito a pressões e a constrangimentos estruturais do sistema internacional que em outras épocas. A esse respeito, julgue (C ou E) os itens a seguir. | A globalização está calcada na cristalização da divisão internacional do trabalho: países da Organização de Cooperação e Desenvolvimento Econômico (OCDE) e do G-7 produzem bens e serviços de alto valor agregado, enquanto os países de renda média e os de menor desenvolvimento relativo especializam-se em produtos de baixa ou de nenhuma intensidade tecnológica. Assim, a dinâmica da globalização torna-se um obstáculo absoluto para que estes últimos se reposicionem competitivamente na divisão internacional do trabalho.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Política Internacional', NULL, 'Q15 Item 3 (TPS 2016): As implicações da globalização para o Estado-nação incluem o impacto sobre sua capacidade de formular autonomamente políticas econômicas no âmbito doméstico, uma vez que ele está muito mais sujeito a pressões e a constrangimentos estruturais do sistema internacional que em outras épocas. A esse respeito, julgue (C ou E) os itens a seguir. | Globalização enseja a livre expansão da mobilidade internacional de fatores de produção, do capital financeiro, de investimentos produtivos — tanto de empresas multinacionais quanto de pequenas e médias empresas —, de conhecimento e de mão de obra qualificada e informal.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Política Internacional', NULL, 'Q15 Item 4 (TPS 2016): As implicações da globalização para o Estado-nação incluem o impacto sobre sua capacidade de formular autonomamente políticas econômicas no âmbito doméstico, uma vez que ele está muito mais sujeito a pressões e a constrangimentos estruturais do sistema internacional que em outras épocas. A esse respeito, julgue (C ou E) os itens a seguir. | O reforço do multilateralismo — como observado a partir da evolução da OMC nas últimas décadas —, os crescentes custos econômicos e políticos do isolamento, a imposição de padrões ambientais, sociais e de segurança, as exigências de competitividade e a busca crescente de maior qualificação profissional, entre outros fatores, limitam consideravelmente as estratégias nacionais de desenvolvimento baseadas em modelos autárquicos ou protecionistas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q16 Item 1 (TPS 2016): Quanto a conceitos básicos e escolas teóricas das relações internacionais, julgue (C ou E) os seguintes itens. | A teoria da interdependência complexa, desenvolvida por institucionalistas liberais como Robert Keohane e Joseph Nye, é caracterizada pela não hierarquização de temas de política internacional.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q16 Item 2 (TPS 2016): Quanto a conceitos básicos e escolas teóricas das relações internacionais, julgue (C ou E) os seguintes itens. | De acordo com o liberalismo institucional, as instituições internacionais, como as Nações Unidas, a Organização Mundial do Comércio e a União Europeia, ajudam a promover a cooperação entre os Estados, mitigando, assim, as consequências da anarquia do sistema internacional.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q16 Item 4 (TPS 2016): Quanto a conceitos básicos e escolas teóricas das relações internacionais, julgue (C ou E) os seguintes itens. | As teorias das relações internacionais formuladas por Hans Morgenthau e, mais recentemente, por John Mearsheimer, ao postularem a promoção da segurança como finalidade última da ação dos Estados, caracterizam-se pelo realismo defensivo. ||263_IRBR_DIPL_1F_001_01N569592|| CESPE | CEBRASPE – IRBr Diplomata – Aplicação: 2016', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Política Internacional', NULL, 'Q17 Item 1 (TPS 2016): Nos governos de Gaspar Dutra (1946-1951) e de Getúlio Vargas (1951-1954), o Brasil teve de se posicionar em relação à nova realidade mundial determinada pela Guerra Fria. No que se refere à política externa brasileira no período mencionado, julgue (C ou E) os itens seguintes. | Em 1947, o Brasil rompeu relações diplomáticas com a União das Repúblicas Socialistas Soviéticas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Política Internacional', NULL, 'Q17 Item 2 (TPS 2016): Nos governos de Gaspar Dutra (1946-1951) e de Getúlio Vargas (1951-1954), o Brasil teve de se posicionar em relação à nova realidade mundial determinada pela Guerra Fria. No que se refere à política externa brasileira no período mencionado, julgue (C ou E) os itens seguintes. | Na IV Reunião de Consulta dos Ministros das Relações Exteriores das Américas, em 1951, o chanceler brasileiro defendeu a necessidade de promoção do desenvolvimento como melhor forma de impedir o avanço da ideologia comunista na América Latina.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Política Internacional', NULL, 'Q17 Item 3 (TPS 2016): Nos governos de Gaspar Dutra (1946-1951) e de Getúlio Vargas (1951-1954), o Brasil teve de se posicionar em relação à nova realidade mundial determinada pela Guerra Fria. No que se refere à política externa brasileira no período mencionado, julgue (C ou E) os itens seguintes. | Sob a justificativa de que o caso grego seria um reflexo da guerra política desenvolvida pelo comunismo internacional nos diversos países, com o objetivo de dominar o mundo, o Brasil apoiou a intervenção de potências ocidentais na guerra civil grega.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Política Internacional', NULL, 'Q17 Item 4 (TPS 2016): Nos governos de Gaspar Dutra (1946-1951) e de Getúlio Vargas (1951-1954), o Brasil teve de se posicionar em relação à nova realidade mundial determinada pela Guerra Fria. No que se refere à política externa brasileira no período mencionado, julgue (C ou E) os itens seguintes. | O Brasil absteve-se na votação da resolução da ONU que, em 1950, declarou ser a República Popular da China culpada pela agressão da Coreia do Norte à Coreia do Sul.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Política Internacional', NULL, 'Q18 Item 1 (TPS 2016): Vistas sob a perspectiva histórica, as relações entre Brasil e China foram definidas como um demorado encontro. De 1843, quando foi instalado o consulado brasileiro em Cantão, aos dias de hoje, afastamento e aproximação deram a tônica desse relacionamento. A respeito desse assunto, julgue (C ou E) os itens que se seguem. | Sob a vigência da Política Externa Independente, em 1961, o Brasil enviou à República Popular da China uma missão comercial chefiada pelo vice-presidente João Goulart, o que agravou a desconfiança dos militares e da direita brasileira para com Goulart.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Política Internacional', NULL, 'Q18 Item 2 (TPS 2016): Vistas sob a perspectiva histórica, as relações entre Brasil e China foram definidas como um demorado encontro. De 1843, quando foi instalado o consulado brasileiro em Cantão, aos dias de hoje, afastamento e aproximação deram a tônica desse relacionamento. A respeito desse assunto, julgue (C ou E) os itens que se seguem. | Fernando Collor de Melo foi o primeiro presidente brasileiro a empreender visita oficial à China e à Ásia continental.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Política Internacional', NULL, 'Q18 Item 3 (TPS 2016): Vistas sob a perspectiva histórica, as relações entre Brasil e China foram definidas como um demorado encontro. De 1843, quando foi instalado o consulado brasileiro em Cantão, aos dias de hoje, afastamento e aproximação deram a tônica desse relacionamento. A respeito desse assunto, julgue (C ou E) os itens que se seguem. | No Brasil, a rigidez ideológica do regime militar, ainda sob o influxo da Guerra Fria, impediu que o país normalizasse suas relações com Pequim, o que somente se deu com a redemocratização, ocorrida em 1985.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Política Internacional', NULL, 'Q18 Item 4 (TPS 2016): Vistas sob a perspectiva histórica, as relações entre Brasil e China foram definidas como um demorado encontro. De 1843, quando foi instalado o consulado brasileiro em Cantão, aos dias de hoje, afastamento e aproximação deram a tônica desse relacionamento. A respeito desse assunto, julgue (C ou E) os itens que se seguem. | Em 1952, no auge da Guerra da Coreia, emblemática de um sistema mundial bipolar, o Brasil oficializou seu apoio à China Nacionalista, instalando embaixada em Taipé.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Política Internacional', NULL, 'Q19 Item 1 (TPS 2016): Desde o advento das reformas empreendidas por Deng Xiaoping — a partir de 1978 —, a China experimenta uma inserção crescente, ampla e contínua na economia global, em termos de crescimento econômico, inovação, investimentos, expansão de infraestrutura, geração de energia, ampliação de mercados e diversificação de exportações. A respeito da expansão dos interesses e da diplomacia econômica chinesa, julgue (C ou E) os itens subsequentes. | A China, empenhada em adotar um novo padrão de crescimento econômico, baseado em indústrias menos intensivas na emissão de gás carbônico, vem buscando restringir investimentos em atividades poluidoras tanto em nível doméstico quanto internacional e, junto com os EUA, comprometeu-se recentemente a retirar gradativamente subsídios a atividades econômicas mantidas à base da queima de combustíveis fósseis.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Política Internacional', NULL, 'Q19 Item 3 (TPS 2016): Desde o advento das reformas empreendidas por Deng Xiaoping — a partir de 1978 —, a China experimenta uma inserção crescente, ampla e contínua na economia global, em termos de crescimento econômico, inovação, investimentos, expansão de infraestrutura, geração de energia, ampliação de mercados e diversificação de exportações. A respeito da expansão dos interesses e da diplomacia econômica chinesa, julgue (C ou E) os itens subsequentes. | Em abril de 2016, a China anunciou programa de exploração de nova rota marítima, na região do Ártico, como forma de expandir suas linhas comerciais no hemisfério norte.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Política Internacional', NULL, 'Q19 Item 4 (TPS 2016): Desde o advento das reformas empreendidas por Deng Xiaoping — a partir de 1978 —, a China experimenta uma inserção crescente, ampla e contínua na economia global, em termos de crescimento econômico, inovação, investimentos, expansão de infraestrutura, geração de energia, ampliação de mercados e diversificação de exportações. A respeito da expansão dos interesses e da diplomacia econômica chinesa, julgue (C ou E) os itens subsequentes. | Não obstante a expansão da oferta chinesa de bens e serviços de alto valor agregado, o país defronta-se com claros limites à expansão de sua competitividade global, diante do estancamento dos seus índices de produtividade do trabalho, desde meados da década passada. ||263_IRBR_DIPL_1F_001_01N569592|| CESPE | CEBRASPE – IRBr Diplomata – Aplicação: 2016', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q20 Item 1 (TPS 2016): Tendo-se tornado a segunda potência econômica mundial neste século — e mesmo a primeira, com base em critérios de poder paritário de compra —, a China iniciou, sob a presidência do premier Xi Jinping, movimento de intensificação de sua influência global, forjando parcerias e expandindo seus interesses políticos em todos os quadrantes do mundo. Julgue (C ou E) os próximos itens, no que se refere a ações prioritárias da política externa chinesa na presente década. | Diante da nova preeminência política da China no cenário global, o país tem reconsiderado, em foros internacionais recentes — como na cúpula dos BRICS, em Fortaleza, em 2014, e na reunião de chanceleres da CELAC, em Pequim, em 2015 —, sua tradicional oposição à reforma do Conselho de Segurança das Nações Unidas, por meio do apoio à fórmula que contempla o acréscimo de seis novos membros permanentes com direito de veto, a maioria dos quais países não industrializados.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q20 Item 2 (TPS 2016): Tendo-se tornado a segunda potência econômica mundial neste século — e mesmo a primeira, com base em critérios de poder paritário de compra —, a China iniciou, sob a presidência do premier Xi Jinping, movimento de intensificação de sua influência global, forjando parcerias e expandindo seus interesses políticos em todos os quadrantes do mundo. Julgue (C ou E) os próximos itens, no que se refere a ações prioritárias da política externa chinesa na presente década. | O incremento do prestígio político da China nos últimos anos pode ser aquilatado pelo novo modelo de relação entre potências (new model of great power relations), sugerido pelos chineses aos EUA em 2013 e adotado no final de 2014, durante o encontro dos presidentes Barack Obama e Xi Jinping, em Washington.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q20 Item 3 (TPS 2016): Tendo-se tornado a segunda potência econômica mundial neste século — e mesmo a primeira, com base em critérios de poder paritário de compra —, a China iniciou, sob a presidência do premier Xi Jinping, movimento de intensificação de sua influência global, forjando parcerias e expandindo seus interesses políticos em todos os quadrantes do mundo. Julgue (C ou E) os próximos itens, no que se refere a ações prioritárias da política externa chinesa na presente década. | No tocante às relações China-Rússia, Pequim absteve-se na votação da Resolução n.º 68/262 da Assembleia-Geral das Nações Unidas, referente à integridade territorial da Ucrânia — ainda que tenha subsequentemente demonstrado respeito pela independência, pela soberania e pela integridade territorial daquele país —, tendo em vista suas sensibilidades específicas em relação ao Tibet.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q20 Item 4 (TPS 2016): Tendo-se tornado a segunda potência econômica mundial neste século — e mesmo a primeira, com base em critérios de poder paritário de compra —, a China iniciou, sob a presidência do premier Xi Jinping, movimento de intensificação de sua influência global, forjando parcerias e expandindo seus interesses políticos em todos os quadrantes do mundo. Julgue (C ou E) os próximos itens, no que se refere a ações prioritárias da política externa chinesa na presente década. | O aumento da influência política chinesa no mundo correspondeu a um aumento da rivalidade com o Japão nos campos político, de defesa e militar, diante de fatos como a adoção, pelos japoneses, de uma nova diretiva de defesa nacional, o fim da proibição de exportações de armas e o aumento do orçamento de defesa.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q21 Item 1 (TPS 2016): O movimento de normalização das relações com Cuba, a partir de 2014, constitui um marco da política externa do governo do presidente Barack Obama para a América Latina. A respeito das relações hemisféricas dos EUA durante a gestão Obama, julgue (C ou E) os itens subsecutivos. | Os EUA indispuseram-se com o secretário-geral da Organização dos Estados Americanos (OEA), que se recusou a convocar sessão do Conselho Permanente da OEA para tratar de alteração da ordem constitucional na Venezuela e do referendo revogatório defendido pela oposição venezuelana.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q21 Item 2 (TPS 2016): O movimento de normalização das relações com Cuba, a partir de 2014, constitui um marco da política externa do governo do presidente Barack Obama para a América Latina. A respeito das relações hemisféricas dos EUA durante a gestão Obama, julgue (C ou E) os itens subsecutivos. | Após anúncio do presidente Obama, em 2014, o governo norte-americano implantou medidas migratórias que beneficiaram milhões de indivíduos sem documentos no país, com a regularização de seu status migratório. A medida amparou majoritariamente imigrantes latinos que passaram a dispor de direitos atribuídos a cidadãos norte-americanos e a imigrantes documentados.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q21 Item 3 (TPS 2016): O movimento de normalização das relações com Cuba, a partir de 2014, constitui um marco da política externa do governo do presidente Barack Obama para a América Latina. A respeito das relações hemisféricas dos EUA durante a gestão Obama, julgue (C ou E) os itens subsecutivos. | As consequências positivas diretas da retomada das relações com Cuba incluem o abrandamento das restrições para que norte-americanos visitem a ilha, o aumento do limite de remessa de recursos financeiros dos EUA para Cuba, o relaxamento das restrições para que empresas norte-americanas exportem para Cuba e o anúncio de investimentos norte-americanos na ilha, em setores como hotelaria, finanças, turismo e comunicações.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q21 Item 4 (TPS 2016): O movimento de normalização das relações com Cuba, a partir de 2014, constitui um marco da política externa do governo do presidente Barack Obama para a América Latina. A respeito das relações hemisféricas dos EUA durante a gestão Obama, julgue (C ou E) os itens subsecutivos. | No plano político, os principais pontos de atrito com o Brasil durante a gestão Obama foram a oposição brasileira à Resolução do Conselho de Segurança das Nações Unidas — aprovada em 2010 e patrocinada pelos EUA — de imposição de sanções econômico-comerciais ao Irã e a revelação, em 2013, da interceptação ilegal de conversas telefônicas de autoridades brasileiras pela Agência de Segurança Nacional dos EUA.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q22 Item 1 (TPS 2016): A respeito das relações internacionais no Oriente Médio, julgue (C ou E) os itens que se seguem. | O grupo islâmico Hamas tem contabilizado sucessivas vitórias nas eleições legislativas ocorridas na Faixa de Gaza, que são realizadas regularmente desde 2006, para mandatos de quatro anos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q22 Item 2 (TPS 2016): A respeito das relações internacionais no Oriente Médio, julgue (C ou E) os itens que se seguem. | A demissão em massa de funcionários públicos ligados ao Partido Ba’ath, de Saddam Hussein, no contexto subsequente à invasão do Iraque, em 2003, contribuiu para ampliar a instabilidade política, econômica e social do país.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q22 Item 3 (TPS 2016): A respeito das relações internacionais no Oriente Médio, julgue (C ou E) os itens que se seguem. | O caráter religioso do regime iniciado com a Revolução Iraniana de 1979 foi referendado pela maioria da população, que optou pelo modelo da República Islâmica em detrimento da monarquia.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q22 Item 4 (TPS 2016): A respeito das relações internacionais no Oriente Médio, julgue (C ou E) os itens que se seguem. | O Irã tem sido acusado por outros países do Oriente Médio de, aproveitando-se do contexto da denominada “Primavera Árabe”, estimular a sublevação de populações xiitas contra os seus governantes sunitas, como estratégia de busca de hegemonia regional. ||263_IRBR_DIPL_1F_001_01N569592|| CESPE | CEBRASPE – IRBr Diplomata – Aplicação: 2016', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q23 Item 1 (TPS 2016): Nas décadas de 60 e 70 do século passado, o Brasil tomou a iniciativa de explorar o potencial hidrelétrico da bacia do rio Paraná, o que gerou repercussões na Argentina e no Paraguai. No que se refere a esse assunto, julgue (C ou E) os seguintes itens. | O Tratado do Rio da Prata, assinado em 1979 por Brasil, Argentina, Paraguai e Uruguai, disciplinou o uso dos rios internacionais da região para a produção de energia elétrica e irrigação agrícola.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q23 Item 2 (TPS 2016): Nas décadas de 60 e 70 do século passado, o Brasil tomou a iniciativa de explorar o potencial hidrelétrico da bacia do rio Paraná, o que gerou repercussões na Argentina e no Paraguai. No que se refere a esse assunto, julgue (C ou E) os seguintes itens. | Com a Ata das Cataratas, de 1966, o Brasil, para atender às necessidades energéticas de industrialização da região Sudeste, comprometeu-se a comprar o excedente de energia paraguaia gerado pela represa hidrelétrica de Yacyretá, pelo prazo de dez anos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q23 Item 3 (TPS 2016): Nas décadas de 60 e 70 do século passado, o Brasil tomou a iniciativa de explorar o potencial hidrelétrico da bacia do rio Paraná, o que gerou repercussões na Argentina e no Paraguai. No que se refere a esse assunto, julgue (C ou E) os seguintes itens. | Em 1973, Brasil e Paraguai assinaram um tratado para o aproveitamento hidrelétrico do rio Paraná, desde Sete Quedas até a foz do rio Iguaçu. Os termos do contrato determinavam a criação da empresa binacional Itaipu e a participação dos dois países, em condições de igualdade, na construção e operação da hidrelétrica e na divisão da energia gerada.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q23 Item 4 (TPS 2016): Nas décadas de 60 e 70 do século passado, o Brasil tomou a iniciativa de explorar o potencial hidrelétrico da bacia do rio Paraná, o que gerou repercussões na Argentina e no Paraguai. No que se refere a esse assunto, julgue (C ou E) os seguintes itens. | O governo argentino defendeu que, antes da construção de represas na bacia do rio Paraná, deveria haver consulta prévia obrigatória aos países ribeirinhos do curso inferior de rios internacionais de curso sucessivo, para evitar prejuízos em seus territórios.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q24 Item 1 (TPS 2016): Durante parte da década de 80 até pelo menos a crise econômica de 2001, o realismo periférico (RP) despontou como importante corrente teórico-metodológica das relações internacionais na América Latina e, em particular, na Argentina. Julgue (C ou E) os seguintes itens, referentes ao arcabouço teórico do RP e (ou) à sua práxis política. | O RP postula um tipo de política externa que corresponde ao conceito de Estado comerciante de Richard Rosecrance, em contraposição à premissa realista clássica segundo a qual os Estados nacionais devem pautar suas políticas externas por considerações de índole político-militar.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q24 Item 3 (TPS 2016): Durante parte da década de 80 até pelo menos a crise econômica de 2001, o realismo periférico (RP) despontou como importante corrente teórico-metodológica das relações internacionais na América Latina e, em particular, na Argentina. Julgue (C ou E) os seguintes itens, referentes ao arcabouço teórico do RP e (ou) à sua práxis política. | Atributo da política exterior argentina dos anos 90, consentâneo com os princípios do RP, foi a adoção de uma “agenda positiva” consubstanciada, por exemplo, na participação do país em missões de paz das Nações Unidas, no apoio aos EUA na Guerra do Golfo e na assinatura de diversos acordos bilaterais de garantias de investimentos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q24 Item 4 (TPS 2016): Durante parte da década de 80 até pelo menos a crise econômica de 2001, o realismo periférico (RP) despontou como importante corrente teórico-metodológica das relações internacionais na América Latina e, em particular, na Argentina. Julgue (C ou E) os seguintes itens, referentes ao arcabouço teórico do RP e (ou) à sua práxis política. | Na sequência da invasão norte-americana do Panamá, em 1989, a Argentina, em atitude condizente com os postulados do RP, foi o único país do continente americano a apoiar os EUA na sessão da OEA realizada em 22/12/1989, em que se aprovou resolução na qual a Organização “lamenta profundamente a intervenção militar no Panamá”.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q25 Item 1 (TPS 2016): A política externa alemã passa por mudanças drásticas, com a diversificação de temas e espaços de atuação, em comparação à agenda anterior, mais restrita a temas da Europa e do G-7. Tendo como referência essas modificações, julgue (C ou E) os itens que se seguem, a respeito da agenda externa alemã contemporânea. | A Alemanha tem-se mostrado disposta a levantar, ou ao menos a atenuar, as sanções impostas à Rússia em decorrência da anexação da Crimeia — considerada ilegal — e da desestabilização deliberada da Ucrânia, caso a Rússia cumpra os Acordos de Minsk, celebrados em fevereiro de 2015.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q25 Item 2 (TPS 2016): A política externa alemã passa por mudanças drásticas, com a diversificação de temas e espaços de atuação, em comparação à agenda anterior, mais restrita a temas da Europa e do G-7. Tendo como referência essas modificações, julgue (C ou E) os itens que se seguem, a respeito da agenda externa alemã contemporânea. | No tocante às relações com o Brasil, destaca-se o importante papel da Alemanha no fortalecimento do sistema brasileiro de inovação, por meio de parcerias, especialmente com a Sociedade Fraunhofer, que permitiram a criação e o desenvolvimento dos Institutos SENAI de Inovação, da Empresa Brasileira de Pesquisa e Inovação Industrial (EMBRAPII), da FINEP – Inovação e Pesquisa e da Empresa Brasileira de Pesquisa Agropecuária (EMBRAPA).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q25 Item 3 (TPS 2016): A política externa alemã passa por mudanças drásticas, com a diversificação de temas e espaços de atuação, em comparação à agenda anterior, mais restrita a temas da Europa e do G-7. Tendo como referência essas modificações, julgue (C ou E) os itens que se seguem, a respeito da agenda externa alemã contemporânea. | As relações teuto-norte-americanas têm sido marcadas por afastamento e até certa hostilidade, diante da revelação, pela plataforma Wikileaks, da interceptação de conversas e documentos reservados, inclusive de altas autoridades alemãs, pela Agência de Segurança Nacional norte-americana (NSA), fato que ensejou a chamada a consultas do embaixador alemão em Washington.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q25 Item 4 (TPS 2016): A política externa alemã passa por mudanças drásticas, com a diversificação de temas e espaços de atuação, em comparação à agenda anterior, mais restrita a temas da Europa e do G-7. Tendo como referência essas modificações, julgue (C ou E) os itens que se seguem, a respeito da agenda externa alemã contemporânea. | As relações entre Alemanha e Turquia ficaram sensivelmente desgastadas após a aprovação, pelo Parlamento alemão, de moção que qualifica de genocídio o massacre de armênios por tropas otomanas em 1915 e 1916, tendo o próprio governo alemão reconhecido que a aprovação da moção tem potencial para desestabilizar as relações bilaterais, especialmente no que tange ao tratamento de temas como refugiados e migrações.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q26 Item 1 (TPS 2016): De acordo com o documento Common Purpose: Towards a more effective OSCE, de junho de 2005, a Organização para a Cooperação e a Segurança na Europa (OSCE) é “a única organização regional para a cooperação em temas de segurança na qual Estados-membros de Vancouver a Vladivostok participam em condições de igualdade”. A respeito da OSCE, julgue (C ou E) os itens a seguir. | Um dos mandatos de maior expressão da OSCE é a ação coordenada dos Estados participantes no combate ao terrorismo. Essa ação, no entanto, é limitada pelos respectivos dispositivos nacionais e multilaterais de respeito aos direitos humanos e ao direito internacional.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q26 Item 2 (TPS 2016): De acordo com o documento Common Purpose: Towards a more effective OSCE, de junho de 2005, a Organização para a Cooperação e a Segurança na Europa (OSCE) é “a única organização regional para a cooperação em temas de segurança na qual Estados-membros de Vancouver a Vladivostok participam em condições de igualdade”. A respeito da OSCE, julgue (C ou E) os itens a seguir. | A OSCE é uma organização voltada para a promoção da segurança internacional dos cinquenta e sete Estados participantes, com foco exclusivo no controle do comércio de armas e de sua não proliferação, no combate ao terrorismo e em medidas de construção e manutenção da paz e da segurança.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q26 Item 3 (TPS 2016): De acordo com o documento Common Purpose: Towards a more effective OSCE, de junho de 2005, a Organização para a Cooperação e a Segurança na Europa (OSCE) é “a única organização regional para a cooperação em temas de segurança na qual Estados-membros de Vancouver a Vladivostok participam em condições de igualdade”. A respeito da OSCE, julgue (C ou E) os itens a seguir. | As resoluções da OSCE, que são tomadas por consenso dos cinquenta e sete países participantes, têm caráter mandatório e vinculante.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q26 Item 4 (TPS 2016): De acordo com o documento Common Purpose: Towards a more effective OSCE, de junho de 2005, a Organização para a Cooperação e a Segurança na Europa (OSCE) é “a única organização regional para a cooperação em temas de segurança na qual Estados-membros de Vancouver a Vladivostok participam em condições de igualdade”. A respeito da OSCE, julgue (C ou E) os itens a seguir. | A OSCE mantém programas de cooperação na área de segurança internacional com a OTAN, as Nações Unidas e a União Europeia. Com a ONU, um dos principais programas refere-se ao apoio à implementação da Resolução n.º 1.540/2004, do Conselho de Segurança, a respeito do controle da proliferação de armas nucleares, químicas e biológicas. ||263_IRBR_DIPL_1F_001_01N569592|| CESPE | CEBRASPE – IRBr Diplomata – Aplicação: 2016 GEOGRAFIA', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Geografia', NULL, 'Q27 Item 1 (TPS 2016): No que diz respeito às principais correntes metodológicas da Geografia e sua aplicação, julgue (C ou E) os itens seguintes. | O fato de a Geografia Humanista considerar o espaço um lugar, extensão carregada de significações, possibilita que ela trate de questões práticas como as que envolvam a percepção ambiental e a valoração arquitetônica.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Geografia', NULL, 'Q27 Item 2 (TPS 2016): No que diz respeito às principais correntes metodológicas da Geografia e sua aplicação, julgue (C ou E) os itens seguintes. | Tanto o planejamento urbano quanto os símbolos patrimoniais ou culturais da formação territorial histórica, dimensões do espaço vivido nas metrópoles que impactam as pessoas, podem ser analisados no viés geográfico crítico.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Geografia', NULL, 'Q27 Item 3 (TPS 2016): No que diz respeito às principais correntes metodológicas da Geografia e sua aplicação, julgue (C ou E) os itens seguintes. | A Geografia Teorética ou Nova Geografia reforça a Geografia Tradicional e desprestigia o planejamento territorial adotado pelo Estado.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Geografia', NULL, 'Q27 Item 4 (TPS 2016): No que diz respeito às principais correntes metodológicas da Geografia e sua aplicação, julgue (C ou E) os itens seguintes. | A Geografia Crítica, ao debater a questão da produção econômica do espaço, reconhece a importância dos agentes hegemônicos do capital na minimização das disparidades urbanas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Geografia', NULL, 'Q28 Item 1 (TPS 2016): Acerca da formação territorial brasileira, julgue (C ou E) os itens a seguir. | A partir da segunda metade do século XIX, a produção e o território se mecanizaram, de forma que às técnicas das máquinas circunscritas à produção sucederam as técnicas das máquinas incluídas no território.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Geografia', NULL, 'Q28 Item 2 (TPS 2016): Acerca da formação territorial brasileira, julgue (C ou E) os itens a seguir. | No decorrer do século XX, o aparelhamento dos portos, a construção de estradas de ferro e as novas formas de participação do país na fase industrial fizeram do Sudeste a região com maior concentração de capital, de modo independente de uma nova regionalização agrária ou urbana brasileira.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Geografia', NULL, 'Q28 Item 3 (TPS 2016): Acerca da formação territorial brasileira, julgue (C ou E) os itens a seguir. | Com a construção de Brasília, a nova capital brasileira, pretendeu-se superar três dificuldades para a implementação do Plano de Metas do então presidente Juscelino Kubistchek: a inexistência de uma localização privilegiada do poder para o rearranjo das economias regionais, em prol da unificação do mercado nacional; o enrijecimento econômico do litoral, palco da colonização; o potencial burguês latifundiário e urbano concentrados nas antigas ilhas territoriais produtivas de café e cana-de-açúcar.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Geografia', NULL, 'Q28 Item 4 (TPS 2016): Acerca da formação territorial brasileira, julgue (C ou E) os itens a seguir. | Nos três primeiros séculos de colonização portuguesa no Brasil, a produção no território brasileiro era fundada na criação de um meio técnico mais dependente do trabalho direto e concreto do homem do que da incorporação de capital à natureza.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q29 Item 1 (TPS 2016): A mundialização não diz respeito apenas às atividades dos grupos empresariais e aos fluxos comerciais que elas provocam. Inclui também a globalização financeira, que não pode ser abstraída da lista das forças às quais deve ser imposta a adaptação dos mais fracos e desguarnecidos. François Chesnais. A mundialização do capital. São Paulo: Xamã, 1996 (com adaptações). Tendo como referência inicial o fragmento de texto apresentado, julgue (C ou E) os itens subsequentes. | A agricultura moderna brasileira elabora usos e apropriações da terra com reduzida demanda de recursos hídricos e maximização da fragmentação do território nacional.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q29 Item 2 (TPS 2016): A mundialização não diz respeito apenas às atividades dos grupos empresariais e aos fluxos comerciais que elas provocam. Inclui também a globalização financeira, que não pode ser abstraída da lista das forças às quais deve ser imposta a adaptação dos mais fracos e desguarnecidos. François Chesnais. A mundialização do capital. São Paulo: Xamã, 1996 (com adaptações). Tendo como referência inicial o fragmento de texto apresentado, julgue (C ou E) os itens subsequentes. | Mundialização do capital ou globalização refletem a capacidade estratégica de grandes grupos oligopolistas, voltados para a produção industrial ou para as principais atividades de serviços, em adotar, por conta própria, enfoque e conduta globais.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q29 Item 3 (TPS 2016): A mundialização não diz respeito apenas às atividades dos grupos empresariais e aos fluxos comerciais que elas provocam. Inclui também a globalização financeira, que não pode ser abstraída da lista das forças às quais deve ser imposta a adaptação dos mais fracos e desguarnecidos. François Chesnais. A mundialização do capital. São Paulo: Xamã, 1996 (com adaptações). Tendo como referência inicial o fragmento de texto apresentado, julgue (C ou E) os itens subsequentes. | O princípio geográfico da localização, no mundo globalizado economicamente competitivo, é superado pelos sistemas técnicos e de informação.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q29 Item 4 (TPS 2016): A mundialização não diz respeito apenas às atividades dos grupos empresariais e aos fluxos comerciais que elas provocam. Inclui também a globalização financeira, que não pode ser abstraída da lista das forças às quais deve ser imposta a adaptação dos mais fracos e desguarnecidos. François Chesnais. A mundialização do capital. São Paulo: Xamã, 1996 (com adaptações). Tendo como referência inicial o fragmento de texto apresentado, julgue (C ou E) os itens subsequentes. | No mundo globalizado, observa-se uma tendência de compartimentação generalizada dos territórios, onde se associam e se chocam o movimento geral da sociedade do trabalho e o movimento particular de cada fração espacial: do nacional ao regional e ao local.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q30 Item 1 (TPS 2016): País de território misto, marcado a um só tempo pela continentalidade e maritimidade, o Brasil tem, na análise dos clássicos da teoria geopolítica relacionados ao poder naval (Mahan) e na da teoria do poder terrestre (Mackinder), importantes questões para a discussão de uma visão estratégica contemporânea, em um contexto em que há um importante aumento da estrutura política e econômica do país no cenário mundial. Ronaldo Gomes Carmona. Geopolítica clássica e geopolítica brasileira contemporânea: | A vasta extensão territorial do Brasil, que corresponde a 47% do território sul-americano, indica a necessidade de segurança das fronteiras com seus países vizinhos, de responsabilidade dos órgãos de segurança pública, da Secretaria da Receita Federal e das forças armadas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q30 Item 2 (TPS 2016): País de território misto, marcado a um só tempo pela continentalidade e maritimidade, o Brasil tem, na análise dos clássicos da teoria geopolítica relacionados ao poder naval (Mahan) e na da teoria do poder terrestre (Mackinder), importantes questões para a discussão de uma visão estratégica contemporânea, em um contexto em que há um importante aumento da estrutura política e econômica do país no cenário mundial. Ronaldo Gomes Carmona. Geopolítica clássica e geopolítica brasileira contemporânea: | Em relação à segurança nacional, as bacias hidrográficas amazônica e do Paraguai são consideradas não prioritárias, em razão de seu isolamento e distanciamento em relação aos grandes centros urbanos do centro-sul do país e também da ocupação rarefeita da população nas regiões onde se situam.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q30 Item 3 (TPS 2016): País de território misto, marcado a um só tempo pela continentalidade e maritimidade, o Brasil tem, na análise dos clássicos da teoria geopolítica relacionados ao poder naval (Mahan) e na da teoria do poder terrestre (Mackinder), importantes questões para a discussão de uma visão estratégica contemporânea, em um contexto em que há um importante aumento da estrutura política e econômica do país no cenário mundial. Ronaldo Gomes Carmona. Geopolítica clássica e geopolítica brasileira contemporânea: | A Política de Defesa Nacional destaca a importância do controle e defesa dos chamados ativos estratégicos do Brasil: fontes de água doce e de energia, biodiversidade, imensas reservas de recursos naturais e extensas áreas a serem incorporadas ao sistema produtivo nacional.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q30 Item 4 (TPS 2016): País de território misto, marcado a um só tempo pela continentalidade e maritimidade, o Brasil tem, na análise dos clássicos da teoria geopolítica relacionados ao poder naval (Mahan) e na da teoria do poder terrestre (Mackinder), importantes questões para a discussão de uma visão estratégica contemporânea, em um contexto em que há um importante aumento da estrutura política e econômica do país no cenário mundial. Ronaldo Gomes Carmona. Geopolítica clássica e geopolítica brasileira contemporânea: | O fato de o Brasil possuir um vasto litoral com importantes reservas de recursos naturais é, por si só, indicativo de que o país deve investir na força naval de defesa de seu território oceânico. ||263_IRBR_DIPL_1F_001_01N569592|| CESPE | CEBRASPE – IRBr Diplomata – Aplicação: 2016', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q31 Item 1 (TPS 2016): No início do século XIX, o conjunto de pressupostos históricos de sistematização da geografia já havia ocorrido: a Terra já estava toda reconhecida; a Europa articulava um espaço de relações econômicas mundial; havia informações dos lugares mais variados da superfície terrestre, bem como representações do globo, devido ao uso cada vez maior de mapas. Antônio Carlos Robert Moraes. Apud: Auro de Jesus Rodrigues. Geografia: introdução à ciência geográfica. São Paulo: Editora Avercamp, 2008 (com ada | On a visit to Beirut during the terrible civil war of 1975-1976 a French journalist wrote regretfully of the gutted downtown area that “it had once seemed to belong to the', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Economia', NULL, 'Q31 Item 2 (TPS 2016): No início do século XIX, o conjunto de pressupostos históricos de sistematização da geografia já havia ocorrido: a Terra já estava toda reconhecida; a Europa articulava um espaço de relações econômicas mundial; havia informações dos lugares mais variados da superfície terrestre, bem como representações do globo, devido ao uso cada vez maior de mapas. Antônio Carlos Robert Moraes. Apud: Auro de Jesus Rodrigues. Geografia: introdução à ciência geográfica. São Paulo: Editora Avercamp, 2008 (com ada | Orient of Chateaubriand and Nerval”. He was right about the place, of course, especially so far as a European was concerned. The Orient was almost a European invention, and 7 had been since antiquity a place of romance, exotic beings, haunting memories and landscapes, remarkable experiences. Now it was disappearing; in a sense it had happened, its time 10 was over. Americans will not feel quite the same about the Orient, which for them is much more likely to be associat', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Inglesa', NULL, 'Q37 Item 3 (TPS 2016): Decide whether the statements below, concerning the ideas and the vocabulary of text II, are right (C) or wrong (E). | In the text, the adjective “totemic” (R.26) is the same as emblematic.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Língua Inglesa', NULL, 'Q37 Item 4 (TPS 2016): Decide whether the statements below, concerning the ideas and the vocabulary of text II, are right (C) or wrong (E). | Globalisation, as a project, intends to respect and promote different futures and dynamics for different countries. Text III 1 Pierre Englebert’s attempt to measure all of Africa using the yardstick of a single historical factor is highly problematic. In this regard, Englebert’s book suffers from four 4 tendencies, the first two of which involve a dominant mode in current writing about Africa, and the third and fourth of which reflect the constraints of academic publishing, particularly in 7 the United States of America. Current writing about Africa is characterised, firstly, by a remarkable tendency to generalise about the entire continent, which no author specialising in 10 Asia, for example, would dare contemplate. This usually involves the extrapolation of a single empirical situation ', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Inglesa', NULL, 'Q38 Item 1 (TPS 2016): Decide whether the following statements, concerning the grammatical and semantic aspects of text III, are right (C) or wrong (E). | Both the author of the book itself and the reviewer agree that African countries should not have had their independence determined by outside forces.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Língua Inglesa', NULL, 'Q38 Item 2 (TPS 2016): Decide whether the following statements, concerning the grammatical and semantic aspects of text III, are right (C) or wrong (E). | Most publications tend to propose explanations for the situation of African and Asian countries in a generalised form.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
